package kz.zani.mobile

import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

@OptIn(ExperimentalCoroutinesApi::class)
class InboxRetryMessageTest {
    private fun fixture(name:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$name.json")!!.bufferedReader().use {it.readText()}
    private fun context(c:JSONObject)=InboxMessageFilesContext(c.getInt("business"),c.getInt("conversation"),c.getInt("message"),c.getInt("epoch"),c.getInt("revision"),c.getInt("limit"))
    private fun repository()=APIReadRepository(ReadTransport {q->val name=if(q.path=="/api/mobile/v1/inbox/")"inbox-${q.query["business"]}" else "inbox-${q.query["business"]}-${q.path.trimEnd('/').substringAfterLast('/')}";ReadResponse(200,fixture(name))})
    private class Held(override val grants:List<SyntheticInboxRetryGrant>):SyntheticInboxRetryPort {
        val attempts=mutableListOf<InboxRetryAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxRetryOutcome>>()
        override suspend fun execute(attempt:InboxRetryAttempt):SyntheticInboxRetryOutcome {attempts+=attempt;return CompletableDeferred<SyntheticInboxRetryOutcome>().also {pending+=it}.await()}
    }
    private class UnknownReply(override val grants:List<SyntheticInboxReplyGrant>):SyntheticInboxReplyPort {override suspend fun execute(attempt:InboxReplyAttempt):SyntheticInboxReplyOutcome=SyntheticInboxReplyOutcome.Unknown}
    private class UnknownHandoff(override val grants:List<SyntheticHandoffGrant>):SyntheticHandoffPort {override suspend fun execute(attempt:HandoffAttempt):SyntheticHandoffOutcome=SyntheticHandoffOutcome.Unknown}
    @Test fun sharedExactSourcePlain201FrozenBodyAndUnknownLedgerContract()=runTest {
        val catalog=JSONObject(fixture("inbox-retry-message"));val c=context(catalog.getJSONObject("context"));val cases=catalog.getJSONArray("source_cases")
        for(i in 0 until cases.length()) {val row=cases.getJSONObject(i);val s=InboxRetryMessageSource.decode(row.getString("response_json"),context(row.getJSONObject("context")));assertEquals(row.getString("name"),row.getBoolean("valid"),s!=null);s?.let {assertTrue(it.valid);assertEquals(row.getBoolean("eligible"),it.eligible)}}
        val receipts=catalog.getJSONArray("receipt_cases")
        for(i in 0 until receipts.length()) {val row=receipts.getJSONObject(i);val s=InboxRetryMessageSource.decode(row.getString("source_json"),c)!!;val r=InboxRetryReceipt.decode(row.getString("response_json"),s);assertEquals(row.getString("name"),row.getBoolean("valid"),r!=null);r?.let {assertEquals(s.text,it.text);assertEquals(s.context.message,it.retryOf);assertNotEquals(s.context.message,it.id)}}
        val source=InboxRetryMessageSource.decode(catalog.getString("source_json"),c)!!;val port=FixtureInboxRetryPort(fixture("inbox-retry-message"));val owner=InboxRetryOwner(101,901,1);val auth=port.grants[0].authorization(owner)!!;val review=InboxRetryReview(source,auth,1);val ledger=InboxRetryLedger();val a=ledger.begin(review)!!
        assertEquals(setOf("message_id"),JSONObject(a.preparedBody()).keys().asSequence().toSet());assertEquals(9012,JSONObject(a.preparedBody()).getInt("message_id"));assertEquals("/api/inbox/conversations/901/retry-message/",a.path);assertTrue(a.headers.isEmpty());assertTrue(a.query.isEmpty());assertNull(ledger.begin(review));assertFalse(ledger.acknowledge(auth,ledger.visible(auth)!!))
        ledger.complete(a,port.execute(a));val result=ledger.visible(auth)!!;assertEquals(InboxRetryPhase.RESPONSE,result.phase);assertEquals(9901,result.result!!.id);ledger.complete(a,SyntheticInboxRetryOutcome.Unknown);assertEquals(result,ledger.visible(auth));assertTrue(ledger.acknowledge(auth,result));val second=ledger.begin(review)!!;assertNotEquals(a.localID,second.localID);assertEquals(a.preparedBody(),second.preparedBody());ledger.complete(second,SyntheticInboxRetryOutcome.Unknown);val unknown=ledger.visible(auth)!!;assertFalse(ledger.acknowledge(auth,unknown));assertNull(ledger.begin(review));assertEquals(second,ledger.records[1].attempt)
        val next=owner.copy(epoch=2);val nextAuth=port.grants[0].authorization(next)!!;assertEquals(unknown,ledger.visible(nextAuth));val reread=source.copy(context=c.copy(epoch=2,revision=2));assertNull(ledger.begin(InboxRetryReview(reread,nextAuth,2)));val actor=SyntheticInboxRetryGrant(101,901,6002,true).authorization(next)!!;assertNull(ledger.visible(actor));assertNull(ledger.begin(InboxRetryReview(reread,actor,3)));assertTrue(ledger.blocked(101,901));assertFalse(ledger.blocked(202,951))
        for(g in listOf(SyntheticInboxRetryGrant(101,901,5001,false),SyntheticInboxRetryGrant(202,901,5001,true),SyntheticInboxRetryGrant(101,951,5001,true),SyntheticInboxRetryGrant(101,901,0,true)))assertNull(g.authorization(owner))
        for(status in listOf(200,403,500)) {val l=InboxRetryLedger();val attempt=l.begin(review)!!;l.complete(attempt,SyntheticInboxRetryOutcome.Response(status,catalog.getJSONArray("scenarios").getJSONObject(0).getString("response_json")));assertEquals(InboxRetryPhase.UNKNOWN,l.visible(auth)!!.phase);assertFalse(l.acknowledge(auth,l.visible(auth)!!))}
    }
    @Test fun actualParentReviewPendingResponseUnknownRereadABAAndSiblingSubmitBarriers()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val fixturePort=FixtureInboxRetryPort(fixture("inbox-retry-message"));val held=Held(fixturePort.grants);val log=mutableListOf<ReadRequest>();val base=FixtureInboxRetryReadTransport(fixture("inbox-retry-message"));val read=APIInboxMessageFilesRepository(ReadTransport {q->log+=q;base.get(q)});val reply=UnknownReply(FixtureInboxReplyPort(fixture("inbox-reply-outcome")).grants);val handoff=UnknownHandoff(FixtureHandoffPort(fixture("inbox-handoff-outcome")).grants);val m=InboxViewModel(repository(),replySubmission=reply,handoffSubmission=handoff,messageFiles=read,retrySubmission=held)
        try {
            m.load(101,411);runCurrent();m.open(901);runCurrent();val row=m.state.thread!!.messages[1];val original=m.state.thread;val child=m.messageMetadata!!;val replyContext=m.reply.state.context!!;m.openMessageFiles(m.messageFilesEntryControl(row));val presentation=m.messageFilesPresentationControl;assertTrue(log.isEmpty());assertFalse(child.canPrepareRetry);child.load(child.control);assertEquals("failed",child.window!!.retrySource!!.status);assertEquals(InboxMessageState.SENT,row.sourceState);assertTrue(child.canPrepareRetry);assertEquals(original,m.state.thread)
            val old=child.control;child.prepareRetry(child.control);val review=child.retryReview!!;val control=child.control;val reads=log.toList();child.load(child.control);child.submitRetry(review,old);child.backRetry(old);assertEquals(review,child.retryReview);assertEquals(reads,log);assertTrue(held.attempts.isEmpty());val job=launch {child.submitRetry(review,control)};runCurrent();val pending=child.retryRecord!!;child.submitRetry(review,child.control);child.acknowledgeRetry(pending,child.control);assertEquals(1,held.attempts.size);assertEquals(InboxRetryPhase.PENDING,pending.phase);assertTrue(m.retryCommandsBlocked)
            m.closeMessageFiles(presentation);m.openReply(replyContext,m.control);m.openHandoff(m.handoff.entryControl,m.control);assertNull(m.reply.control);assertNull(m.handoff.control);m.reply.open(replyContext);m.reply.update(" Must not bypass retry ",m.reply.inputControl);m.reply.prepare(m.reply.control);assertFalse(m.reply.canSubmit);m.reply.submit(m.reply.state.review!!,m.reply.control);assertEquals(0,m.reply.retainedAttemptCount);m.reply.close(m.reply.returnControl);m.openMessageFiles(m.messageFilesEntryControl(row));child.load(child.control);assertEquals(reads,log);assertEquals(pending,child.retryRecord);assertNull(child.window)
            held.pending[0].complete(fixturePort.execute(held.attempts[0]));job.join();val response=child.retryRecord!!;assertEquals(InboxRetryPhase.RESPONSE,response.phase);assertEquals(9901,response.result!!.id);assertEquals(original,m.state.thread);child.acknowledgeRetry(response,control);assertEquals(response,child.retryRecord);child.acknowledgeRetry(response,child.control);assertFalse(m.retryCommandsBlocked);assertEquals(1,child.retainedRetryCount)
            child.load(child.control);child.prepareRetry(child.control);val second=child.retryReview!!;val next=launch {child.submitRetry(second,child.control)};runCurrent();held.pending[1].complete(SyntheticInboxRetryOutcome.Unknown);next.join();val unknown=child.retryRecord!!;child.acknowledgeRetry(unknown,child.control);child.load(child.control);child.prepareRetry(child.control);assertEquals(2,held.attempts.size);assertEquals(unknown,child.retryRecord);assertNull(child.retryReview);assertTrue(m.retryCommandsBlocked)
            m.closeMessageFiles(m.messageFilesPresentationControl);m.retryThread(m.threadSelection);runCurrent();m.openMessageFiles(m.messageFilesEntryControl(m.state.thread!!.messages[1]));child.load(child.control);assertEquals(unknown,child.retryRecord);assertNotEquals(unknown.attempt.review.source.context.revision,child.window!!.context.revision);m.closeMessageFiles(m.messageFilesPresentationControl);m.load(202,412);runCurrent();m.open(951);runCurrent();m.openMessageFiles(m.messageFilesEntryControl(m.state.thread!!.messages[1]));child.load(child.control);assertNull(child.retryRecord);assertTrue(child.canPrepareRetry);assertFalse(m.retryCommandsBlocked);m.closeMessageFiles(m.messageFilesPresentationControl);m.load(101,413);runCurrent();m.open(901);runCurrent();m.openMessageFiles(m.messageFilesEntryControl(m.state.thread!!.messages[0]));child.load(child.control);assertEquals(9011,child.context!!.message);assertEquals(9012,child.retryRecord!!.attempt.review.source.context.message);assertEquals(unknown,child.retryRecord);assertTrue(m.retryCommandsBlocked);assertFalse(child.canPrepareRetry)
            m.closeMessageFiles(m.messageFilesPresentationControl);m.handoff.open(m.handoff.entryControl);m.handoff.update(" Must not bypass retry ",m.handoff.inputControl);m.handoff.prepare(m.handoff.control);assertFalse(m.handoff.canSubmit);m.handoff.submit(m.handoff.state.review!!,m.handoff.control);assertEquals(0,m.handoff.retainedAttemptCount)
        } finally {m.viewModelScope.cancel();Dispatchers.resetMain()}
    }
    @Test fun inverseUnknownReplyAndHandoffLateForeignCompletionAndDefaultPort()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val fixturePort=FixtureInboxRetryPort(fixture("inbox-retry-message"));val held=Held(fixturePort.grants);val reads=APIInboxMessageFilesRepository(FixtureInboxRetryReadTransport(fixture("inbox-retry-message")));val reply=UnknownReply(FixtureInboxReplyPort(fixture("inbox-reply-outcome")).grants);val handoff=UnknownHandoff(FixtureHandoffPort(fixture("inbox-handoff-outcome")).grants)
        val a=InboxViewModel(repository(),replySubmission=reply,messageFiles=reads,retrySubmission=held);val b=InboxViewModel(repository(),handoffSubmission=handoff,messageFiles=reads,retrySubmission=held);val late=InboxViewModel(repository(),messageFiles=reads,retrySubmission=held);val none=InboxViewModel(repository(),messageFiles=reads)
        try {
            a.load(101,414);runCurrent();a.open(901);runCurrent();a.openReply(a.reply.state.context!!,a.control);a.reply.update(" Retained unknown reply ",a.reply.inputControl);a.reply.prepare(a.reply.control);a.reply.submit(a.reply.state.review!!,a.reply.control);val original=a.reply.submission!!;a.reply.close(a.reply.returnControl);a.openMessageFiles(a.messageFilesEntryControl(a.state.thread!!.messages[1]));val ac=a.messageMetadata!!;ac.load(ac.control);ac.prepareRetry(ac.control);assertTrue(held.attempts.isEmpty());assertFalse(ac.canPrepareRetry);assertNull(ac.retryReview);assertEquals(original,a.reply.submission)
            b.load(101,415);runCurrent();b.open(901);runCurrent();b.openHandoff(b.handoff.entryControl,b.control);b.handoff.update(" Retained unknown handoff ",b.handoff.inputControl);b.handoff.prepare(b.handoff.control);b.handoff.submit(b.handoff.state.review!!,b.handoff.control);val old=b.handoff.record!!;b.handoff.back(b.handoff.returnControl);b.openMessageFiles(b.messageFilesEntryControl(b.state.thread!!.messages[1]));val bc=b.messageMetadata!!;bc.load(bc.control);bc.prepareRetry(bc.control);assertTrue(held.attempts.isEmpty());assertFalse(bc.canPrepareRetry);assertEquals(old,b.handoff.record)
            late.load(101,416);runCurrent();late.open(901);runCurrent();late.openMessageFiles(late.messageFilesEntryControl(late.state.thread!!.messages[1]));val child=late.messageMetadata!!;child.load(child.control);child.prepareRetry(child.control);val review=child.retryReview!!;val pending=launch {child.submitRetry(review,child.control)};runCurrent();late.closeMessageFiles(late.messageFilesPresentationControl);late.load(202,417);runCurrent();late.open(951);runCurrent();late.openReply(late.reply.state.context!!,late.control);late.reply.update(" Current Business B input ",late.reply.inputControl);val peer=late.reply.control;val before=late.state.thread;held.pending[0].complete(fixturePort.execute(held.attempts[0]));pending.join();assertNull(child.retryRecord);assertNull(child.window);assertEquals(1,child.retainedRetryCount);assertEquals(peer,late.reply.control);assertEquals(" Current Business B input ",late.reply.state.text);assertEquals(before,late.state.thread)
            none.load(101,418);runCurrent();none.open(901);runCurrent();none.openMessageFiles(none.messageFilesEntryControl(none.state.thread!!.messages[1]));val nc=none.messageMetadata!!;nc.load(nc.control);nc.prepareRetry(nc.control);assertFalse(nc.canPrepareRetry);assertNull(nc.retryReview);assertEquals(0,nc.retainedRetryCount)
        } finally {listOf(a,b,late,none).forEach {it.viewModelScope.cancel()};Dispatchers.resetMain()}
    }
}
